  "source_title": "hypertherm_powermax30_air_service_manual_rev4_808850.pdf",
  "nodes": {
    "Component": [
      {
        "component_id": "comp_internal_compressor",
        "name": "Internal compressor",
        "description": "Compressor checked by connecting it to an external 12 VDC power source; the manual instructs replacing it if it does not run and blow air from the torch.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_solenoid_valve",
        "name": "Solenoid valve",
        "description": "Valve with a gas shut-off override button and gas supply hoses; the manual describes repositioning it and checking that its hoses are secure.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-driver board",
        "description": "Board with diagnostic LED D5 and connectors used in compressor troubleshooting tests.",
        "category": "electrical"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "Board tested for VBUS and compressor-enable voltage during compressor troubleshooting.",
        "category": "electrical"
      },
      {
        "component_id": "comp_connector",
        "name": "Connector",
        "description": "Connectors J1, J2, J3, and J9 are referenced in board voltage checks and disconnection steps.",
        "category": "electrical"
      },
      {
        "component_id": "comp_twisted_pair_wires",
        "name": "J1-to-J9 twisted pair wires",
        "description": "Twisted pair wires connecting the compressor-driver board to the power board; the manual instructs replacing them when compressor-enable voltage is present at J9 but absent at J1.",
        "category": "electrical"
      },
      {
        "component_id": "comp_diagnostic_led",
        "name": "Diagnostic LED D5",
        "description": "Green diagnostic LED on the compressor-driver board observed while the torch is being fired.",
        "category": "indicator"
      }
    ],
    "Symptom": [],
    "FailureMode": [],
    "CorrectiveAction": [],
    "ErrorCode": []
  },
  "relations": []
}
